1	import Foundation
2	import Observation
3	import ReachyKit
4	
5	/// Speaker and microphone levels.
6	///
7	/// The sliders track a local value and only reach the daemon when a gesture ends:
8	/// `POST /api/volume/set` plays a test sound on every accepted call, so a slider
9	/// that sent on change would make the robot beep continuously.
10	@MainActor
11	@Observable
12	final class AudioSettingsModel {
13	    var speakerPercent: Double = 0
14	    var microphonePercent: Double = 0
15	
16	    private(set) var speaker: AudioLevel?
17	    private(set) var microphone: AudioLevel?
18	    /// Nil while unread, and nil again for a board somebody tuned by hand — the two
19	    /// are told apart by ``canTuneProfile``, which is false until the read succeeds.
20	    private(set) var profile: MicrophoneProfile?
21	    private(set) var canTuneProfile = false
22	    private(set) var isLoading = false
23	    private(set) var isBusy = false
24	    private(set) var errorMessage: String?
25	
26	    private var hasLoaded = false
27	
28	    var isReady: Bool {
29	        speaker != nil || microphone != nil
30	    }
31	
32	    /// Safe to call from `.task` on every appearance — it fetches once and then
33	    /// leaves the sliders alone, so a redraw can never yank a value the user is
34	    /// in the middle of dragging.
35	    func load(session: RobotSession) async {
36	        guard !hasLoaded, !isLoading else { return }
37	        isLoading = true
38	        defer { isLoading = false }
39	        do {
40	            // Sequential rather than concurrent: two calls against a robot that
41	            // has no audio device would report the same failure twice.
42	            try await adoptSpeaker(session.volume())
43	            try await adoptMicrophone(session.microphoneVolume())
44	            errorMessage = nil
45	            hasLoaded = true
46	            await loadProfile(session: session)
47	        } catch {
48	            errorMessage.recordDaemonFailure(error)
49	        }
50	    }
51	
52	    func commitSpeaker(session: RobotSession) async {
53	        let percent = Int(speakerPercent.rounded())
54	        // Touching the slider without moving it must not trigger the test sound.
55	        guard percent != speaker?.percent else { return }
56	        await perform { try await adoptSpeaker(session.setVolume(percent)) }
57	    }
58	
59	    func commitMicrophone(session: RobotSession) async {
60	        let percent = Int(microphonePercent.rounded())
61	        guard percent != microphone?.percent else { return }
62	        await perform { try await adoptMicrophone(session.setMicrophoneVolume(percent)) }
63	    }
64	
65	    /// Reads the audio board back, after the levels and never with them.
66	    ///
67	    /// It costs one USB round trip per register — the daemon opens and closes a
68	    /// handle for each — and it is the one part of this screen a robot can lack, so a
69	    /// failure here leaves the levels working and hides the profile row instead of
70	    /// reporting an error over them.
71	    private func loadProfile(session: RobotSession) async {
72	        guard session.canTuneAudio else { return }
73	        do {
74	            profile = try await session.microphoneProfile()
75	            canTuneProfile = true
76	        } catch {
77	            canTuneProfile = false
78	        }
79	    }
80	
81	    /// - Important: this writes the robot's audio board, not a per-session setting.
82	    ///   Every app on the robot hears through the registers it moves.
83	    func applyProfile(_ profile: MicrophoneProfile, session: RobotSession) async {
84	        await perform {
85	            try await session.applyMicrophoneProfile(profile)
86	            self.profile = profile
87	        }
88	    }
89	
90	    func playTestSound(session: RobotSession) async {
91	        await perform { try await session.playTestSound() }
92	    }
93	
94	    private func perform(_ call: () async throws -> Void) async {
95	        isBusy = true
96	        defer { isBusy = false }
97	        do {
98	            try await call()
99	            errorMessage = nil
100	        } catch {
101	            errorMessage.recordDaemonFailure(error)
102	        }
103	    }
104	
105	    /// The daemon answers with what it actually applied, which may be clamped, so
106	    /// the slider follows the robot rather than the other way round.
107	    private func adoptSpeaker(_ level: AudioLevel) {
108	        speaker = level
109	        speakerPercent = Double(level.percent)
110	    }
111	
112	    private func adoptMicrophone(_ level: AudioLevel) {
113	        microphone = level
114	        microphonePercent = Double(level.percent)
115	    }
116	}
117	
118	#if DEBUG
119	    extension AudioSettingsModel {
120	        /// Already loaded, so the view's `.task` returns immediately and the first rendered frame
121	        /// is the final one. Lives here rather than in `Previews/` because it writes members that
122	        /// are private to this file.
123	        static func preview(
124	            speaker: AudioLevel? = .previewSpeaker,
125	            microphone: AudioLevel? = .previewMicrophone,
126	            isLoading: Bool = false,
127	            isBusy: Bool = false,
128	            errorMessage: String? = nil,
129	            profile: MicrophoneProfile? = .standard,
130	            canTuneProfile: Bool = true
131	        ) -> AudioSettingsModel {
132	            let model = AudioSettingsModel()
133	            model.speaker = speaker
134	            model.microphone = microphone
135	            model.speakerPercent = Double(speaker?.percent ?? 0)
136	            model.microphonePercent = Double(microphone?.percent ?? 0)
137	            model.isLoading = isLoading
138	            model.isBusy = isBusy
139	            model.errorMessage = errorMessage
140	            model.profile = profile
141	            model.canTuneProfile = canTuneProfile
142	            model.hasLoaded = true
143	            return model
144	        }
145	    }
146	#endif
